UPDATE CART
SET TOTAL_PRICE = (
SELECT NVL(SUM(ci.QUANTITY * po.PRICE), 0)
FROM CART_ITEMS ci
JOIN PRODUCT_OPTION po
ON ci.PRODUCT_OPTION_ID = po.PRODUCT_OPTION_ID
WHERE ci.CART_ID = #{cart_id}
)
WHERE CART_ID = #{cart_id}
